describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: -5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer bracket upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            99.9,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // Product with no weight
      expect(calc.computeShippingCents([makeLine("a", 1)], 1000)).toBe(0);
    });

    it("selects first bracket when weight is at boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 500g exactly → first bracket (300)
      expect(
        calc.computeShippingCents([makeLine("a", 1, 500)], 1000),
      ).toBe(300);
    });

    it("selects first bracket when weight is below boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 1, 200)], 1000),
      ).toBe(300);
    });

    it("selects second bracket when weight exceeds first boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 1, 501)], 1000),
      ).toBe(700);
    });

    it("selects last bracket at upper boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 1, 5000)], 1000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      expect(
        calc.computeShippingCents([makeLine("a", 1, 6000)], 1000),
      ).toBe(2000);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 1, 9999)], 1000),
      ).toBe(1200);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 2 × 300g = 600g → second bracket (700)
      expect(
        calc.computeShippingCents([makeLine("a", 2, 300)], 1000),
      ).toBe(700);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(
        calc.computeShippingCents([makeLine("a", 1, 400)], 1000),
      ).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(id: string, price = 1000): Product {
  return { id, name: id, unitPriceCents: price };
}

function makeLine(id: string, quantity: number, price = 1000): CartLine {
  return { product: makeProduct(id, price), quantity };
}

describe("InventoryError", () => {
  it("has correct name and properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("supports undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 1, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(2000)
        .mockResolvedValueOnce(3000),
    };
    const lines = [makeLine("a", 1, 1000), makeLine("b", 2, 1500)];
    const result = await refreshPrices(lines, fetcher);

    expect(result).toHaveLength(2);
    expect(result[0].product.unitPriceCents).toBe(2000);
    expect(result[0].quantity).toBe(1);
    expect(result[1].product.unitPriceCents).toBe(3000);
    expect(result[1].quantity).toBe(2);
  });

  it("preserves other product properties", async () => {
    const product: Product = {
      id: "p1",
      name: "Widget",
      unitPriceCents: 100,
      weightGrams: 500,
      currency: "EUR",
    };
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };
    const result = await refreshPrices([{ product, quantity: 1 }], fetcher);
    expect(result[0].product.weightGrams).toBe(500);
    expect(result[0].product.currency).toBe("EUR");
    expect(result[0].product.name).toBe("Widget");
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(
      refreshPrices([makeLine("a", 1)], fetcher),
    ).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(
      refreshPrices([makeLine("a", 1)], fetcher),
    ).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
    };
    await expect(
      refreshPrices([makeLine("a", 1)], fetcher),
    ).rejects.toThrow("network error");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("does not mutate original lines", async () => {
    const original = [makeLine("a", 1, 100)];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    await refreshPrices(original, fetcher);
    expect(original[0].product.unitPriceCents).toBe(100);
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker, InventoryDecision } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

function makeProduct(
  id: string,
  price = 1000,
  weight?: number,
): Product {
  return { id, name: id, unitPriceCents: price, weightGrams: weight };
}

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding the same product again", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      cart.add(makeProduct("a", 500), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a"), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a"), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a"), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of an existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 5);
      cart.updateQuantity("a", 3);
      expect(cart.itemCount).toBe(3);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 5);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("a")).toBe(false);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("missing", 1)).toThrow(
        "Product missing is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 1);
      cart.add(makeProduct("b"), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);

      // Mutating snapshot does not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents × quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.add(makeProduct("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("returns zero totals for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(0);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(0);
    });

    it("applies discount via injected DiscountPolicy", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(200);
      expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        region: "US-CA",
      });
      cart.add(makeProduct("a", 1000), 1);
      cart.totals();
      // Tax should be called with discounted subtotal (1000 - 200 = 800)
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    });

    it("computes shipping with discounted subtotal", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(599),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        shippingCalculator: mockShipping,
      });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800, // discounted subtotal
      );
      expect(totals.shippingCents).toBe(599);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(72),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        shippingCalculator: mockShipping,
      });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      // subtotal=1000, discount=100, discounted=900, tax=72, shipping=500
      expect(totals.totalCents).toBe(900 + 72 + 500);
    });

    it("clamps negative tax to 0", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-10),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-10),
      };
      const cart = new Cart({ shippingCalculator: mockShipping });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("defaults region to US", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(makeProduct("a", 1000), 1);
      cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });
  });

  describe("checkout", () => {
    it("returns totals and lines for simple checkout", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.id).toBe("a");
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(750),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1500); // 750 × 2
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("checks inventory and passes when available", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(1000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
