      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(50),
      ]);
      // 10% of 1000 = 100, fixed 50 = 50, sum = 150
      expect(composite.computeDiscountCents(1000)).toBe(150);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining = 900
          new FixedAmountDiscountPolicy(200), // min(200, 900) = 200
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("ordering matters in chain mode", () => {
      const pols = [
        new FixedAmountDiscountPolicy(200), // 200 off 1000, remaining = 800
        new PercentageDiscountPolicy(10), // 10% of 800 = 80
      ];
      const composite = new CompositeDiscountPolicy(pols, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(280);
    });

    it("chain never exceeds subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "chain",
      );
      // First: min(600, 1000) = 600, remaining = 400. Second: min(600, 400) = 400.
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps negative child results in chain mode", () => {
      const negativePol = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativePol, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // First: max(0, -100) = 0, min(0, 1000) = 0. Remaining = 1000. Second: min(200, 1000) = 200.
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });

    it("returns 0 for zero subtotal in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

