import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker, InventoryDecision } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

function makeProduct(
  id: string,
  price = 1000,
  weight?: number,
): Product {
  return { id, name: id, unitPriceCents: price, weightGrams: weight };
}

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding the same product again", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      cart.add(makeProduct("a", 500), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a"), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a"), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a"), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unit price", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of an existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 5);
      cart.updateQuantity("a", 3);
      expect(cart.itemCount).toBe(3);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 5);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("a")).toBe(false);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("missing", 1)).toThrow(
        "Product missing is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct("a"), 1);
      cart.add(makeProduct("b"), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);

      // Mutating snapshot does not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents × quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.add(makeProduct("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("returns zero totals for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(0);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(0);
    });

    it("applies discount via injected DiscountPolicy", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(200);
      expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        region: "US-CA",
      });
      cart.add(makeProduct("a", 1000), 1);
      cart.totals();
      // Tax should be called with discounted subtotal (1000 - 200 = 800)
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    });

    it("computes shipping with discounted subtotal", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(599),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        shippingCalculator: mockShipping,
      });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800, // discounted subtotal
      );
      expect(totals.shippingCents).toBe(599);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(72),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        shippingCalculator: mockShipping,
      });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      // subtotal=1000, discount=100, discounted=900, tax=72, shipping=500
      expect(totals.totalCents).toBe(900 + 72 + 500);
    });

    it("clamps negative tax to 0", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-10),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-10),
      };
      const cart = new Cart({ shippingCalculator: mockShipping });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("defaults region to US", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(makeProduct("a", 1000), 1);
      cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });
  });

  describe("checkout", () => {
    it("returns totals and lines for simple checkout", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.id).toBe("a");
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(750),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1500); // 750 × 2
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("checks inventory and passes when available", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(1000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "sold out",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const ie = e as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(2);
        expect(ie.message).toBe("sold out");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const ie = e as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(3);
      }
    });

    it("uses asyncTaxProvider when supplied", async () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(0),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        shippingCalculator: mockShipping,
        region: "US-CA",
      });
      cart.add(makeProduct("a", 1000), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100); // 10% of 1000
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("computes async tax on discounted subtotal", async () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({ discountPolicy: mockDiscount, region: "FR" });
      cart.add(makeProduct("a", 1000), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // Subtotal=1000, discount=200, discounted=800, tax=20% of 800=160
      expect(result.totals.taxCents).toBe(160);
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ shippingCalculator: mockShipping });
      cart.add(makeProduct("a", 100), 2);
      cart.add(makeProduct("b", 200), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(150)
          .mockResolvedValueOnce(300),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed: a=150×2=300, b=300×1=300, subtotal=600
      // Discount=0, tax=5% of 600=30, shipping=500
      expect(result.totals.subtotalCents).toBe(600);
      expect(result.totals.taxCents).toBe(30);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(600 + 30 + 500);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "fetch failed",
      );
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("first inventory denial wins when multiple items fail", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 1);
      cart.add(makeProduct("b", 500), 1);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockImplementation(
          async (productId: string): Promise<InventoryDecision> => {
            if (productId === "a") {
              return { available: false, reason: "a is gone" };
            }
            return { available: false, reason: "b is gone" };
          },
        ),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        // The first item checked should fail first
        expect((e as InventoryError).productId).toBe("a");
      }
    });

    it("checkout with no collaborators uses sync totals", async () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(50),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(makeProduct("a", 1000), 1);
      const result = await cart.checkout();
      expect(result.totals.taxCents).toBe(50);
      expect(mockTax.computeTaxCents).toHaveBeenCalled();
    });

    it("InventoryError has correct default message for partial stock", async () => {
      const cart = new Cart();
      cart.add(makeProduct("x", 500), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 2,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (e) {
        const ie = e as InventoryError;
        expect(ie.message).toContain("insufficient stock");
        expect(ie.message).toContain("x");
        expect(ie.available).toBe(2);
      }
    });
  });
});

